import crypto from "node:crypto"; import { NextRequest } from "next/server"; import { z } from "zod"; import { requirePermission } from "@/server/auth/permissions"; import { withActorTransaction } from "@/server/db"; import { assertSameOrigin,fail,ok,parseBody } from "@/server/http";
const input=z.object({code:z.string().trim().min(2).max(40),name:z.string().trim().min(2).max(160),phone:z.string().max(40).optional(),email:z.email().optional(),address:z.string().max(1000).optional(),paymentTermsDays:z.coerce.number().int().min(0).max(365).default(0)});
export async function GET(request:NextRequest){try{const requestId=crypto.randomUUID();const u=await requirePermission(request,requestId,"purchasing.read");const d=await withActorTransaction({userId:u.id,role:u.role,requestId},async c=>(await c.query("SELECT id,code,name,phone,email,payment_terms_days AS \"paymentTermsDays\" FROM app.vendors WHERE is_active=true ORDER BY name")).rows);return ok(d,{requestId});}catch(e){return fail(e);}}
export async function POST(request:NextRequest){try{assertSameOrigin(request);const requestId=crypto.randomUUID();const u=await requirePermission(request,requestId,"purchasing.write");const b=await parseBody(request,input);const d=await withActorTransaction({userId:u.id,role:u.role,requestId},async c=>(await c.query("INSERT INTO app.vendors(code,name,phone,email,address,payment_terms_days) VALUES($1,$2,$3,$4,$5,$6) RETURNING id,code,name",[b.code,b.name,b.phone||null,b.email||null,b.address||null,b.paymentTermsDays])).rows[0]);return ok(d,{requestId});}catch(e){return fail(e);}}
